#include <linux/fs.h>
#include <linux/cpu.h>
#include <linux/errno.h>

int open_msr(struct inode *inode, struct file *file) {
    int cpu;
    int rc;

    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    cpu = smp_processor_id();
    if (cpu >= nr_cpu_ids || !cpu_online(cpu))
        return -ENXIO;

    rc = msr_probe_cpu(cpu);
    if (rc)
        return -EIO;

    return 0;
}

int open_msr(struct inode *inode, struct file *file) {
    int cpu;

    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    cpu = get_cpu_from_path(file->f_path.dentry->d_name.name);
    if (cpu < 0)
        return -ENXIO;

    if (!cpu_online(cpu))
        return -ENXIO;

    if (!msr_ops_supported(cpu))
        return -EIO;

    return 0;
}

#include <linux/fs.h>
#include <linux/errno.h>
#include <linux/cpu.h>
#include <linux/slab.h>

int open_msr(struct inode *inode, struct file *file) {
    int cpu;

    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    cpu = smp_find_cpu_by_flat_num(minor(inode->i_rdev));
    if (cpu < 0)
        return -ENXIO;

    if (!cpu_online(cpu))
        return -ENXIO;

    if (!boot_cpu_has(X86_FEATURE_MSR))
        return -EIO;

    return 0;
}

